import {writeFileSync} from 'node:fs';
import {encounters} from '../src/encounters.js';

const keys=['label','description','skill','dc','success','failure','clue','flag'];
const lines=[
  '-- Generated by npm run campaign:sql. Apply after 002_secure_campaign.sql.',
  "alter table public.campaign_chapters add column if not exists scenes jsonb not null default '[]'::jsonb;"
];
encounters.forEach((chapter,id)=>{
  const json=JSON.stringify(chapter.map(scene=>Object.fromEntries(keys.map((key,i)=>[key,scene[i]]))));
  lines.push(`update public.campaign_chapters set scenes='${json.replaceAll("'","''")}'::jsonb where id=${id};`);
});
writeFileSync(new URL('../db/003_encounters.sql',import.meta.url),lines.join('\n')+'\n');
